// EDUVERSE chunk: B — generated by build-split.js from canonical bank files. Do not hand-edit.
window.EDUVERSE_BANK_B = [{"bahas":"Nelayan menggunakan jala sebagai alat untuk menangkap ikan, sama seperti penjahit menggunakan jarum sebagai alat untuk menjahit. Pasangan lain menunjukkan hubungan orang dengan hasil pekerjaan atau orang dengan pihak yang dilayani, bukan hubungan orang dengan alat yang dipakai untuk bekerja.","id":"BPU01","kunci":1,"opsi":["Petani : Gabah","Penjahit : Jarum","Penyanyi : Penonton","Pelayan : Pelanggan","Arsitek : Gedung"],"soal":"Pasangan kata Nelayan : Jala memiliki hubungan tertentu. Pasangan kata manakah yang memiliki hubungan yang sama?","subtes":"Penalaran Umum"},{"bahas":"Semua siswa kelas olahraga termasuk anggota klub renang, dan semua anggota klub renang bisa berenang gaya bebas, sehingga semua siswa kelas olahraga juga bisa berenang gaya bebas. Pernyataan lain membalik hubungan yang dinyatakan premis, bertentangan dengan premis, atau menyatakan hal yang mungkin terjadi tetapi tidak dijamin oleh premis.","id":"BPU02","kunci":3,"opsi":["Sebagian siswa kelas olahraga tidak bisa berenang gaya bebas.","Semua orang yang bisa berenang gaya bebas adalah anggota klub renang.","Tidak ada siswa kelas olahraga yang menjadi anggota klub renang.","Semua siswa kelas olahraga bisa berenang gaya bebas.","Sebagian anggota klub renang bukan siswa kelas olahraga."],"soal":"Perhatikan dua premis berikut. Premis 1: Semua anggota klub renang bisa berenang gaya bebas. Premis 2: Semua siswa kelas olahraga adalah anggota klub renang. Manakah kesimpulan yang tepat berdasarkan kedua premis tersebut?","subtes":"Penalaran Umum"},{"bahas":"Yuda menempati posisi paling timur. Tono berada tepat di sebelah barat Sinta sehingga Tono dan Sinta membentuk pasangan berurutan, sedangkan Raka harus berada di sebelah barat Tono. Susunan yang memenuhi semua syarat, termasuk syarat bahwa Wulan tidak berada di posisi paling barat, hanya Raka-Tono-Sinta-Wulan-Yuda dan Raka-Wulan-Tono-Sinta-Yuda. Pada semua susunan yang memenuhi syarat, Raka selalu menempati posisi paling barat, sedangkan posisi Tono, Sinta, dan Wulan dapat berubah.","id":"BPU03","kunci":0,"opsi":["Raka berada di posisi paling barat.","Tono berada di posisi kedua.","Sinta berada di posisi ketiga.","Wulan berada tepat di sebelah timur Sinta.","Wulan berada di posisi kedua."],"soal":"Lima perahu nelayan, yaitu Raka, Sinta, Tono, Wulan, dan Yuda, sandar di dermaga pada posisi 1 (paling barat) sampai posisi 5 (paling timur). Diketahui: Tono berada tepat di sebelah barat Sinta; Raka berada di sebelah barat Tono; Yuda berada di posisi paling timur; Wulan tidak berada di posisi paling barat. Manakah pernyataan yang pasti benar?","subtes":"Penalaran Umum"},{"bahas":"Setiap suku diperoleh dengan mengalikan suku sebelumnya dengan 3 lalu mengurangi 2: 5 dikali 3 dikurangi 2 sama dengan 13, 13 dikali 3 dikurangi 2 sama dengan 37, 37 dikali 3 dikurangi 2 sama dengan 109, dan 109 dikali 3 dikurangi 2 sama dengan 325. Suku berikutnya adalah 325 dikali 3 dikurangi 2, yaitu 973.","id":"BPU04","kunci":4,"opsi":["651","975","650","977","973"],"soal":"Perhatikan pola bilangan berikut: 5, 13, 37, 109, 325, ... Bilangan berikutnya dalam pola tersebut adalah ...","subtes":"Penalaran Umum"},{"bahas":"Aturan pelabuhan mewajibkan setiap pengemudi yang membawa mobil ke kapal feri menunjukkan surat kendaraan dan membeli tiket kendaraan. Bagas membawa mobil ke kapal feri, sehingga syarat tersebut berlaku untuk Bagas. Hal lain seperti pengalaman menyeberang, jumlah mobil, ketepatan tiba, atau penumpang lain tidak dinyatakan dalam informasi yang diberikan.","id":"BPU05","kunci":2,"opsi":["Bagas adalah pengemudi yang baru pertama kali menyeberang dengan kapal feri.","Bagas membawa lebih dari satu mobil ke kapal feri hari ini.","Bagas menunjukkan surat kendaraan dan membeli tiket kendaraan.","Bagas akan tiba di tujuan tepat waktu.","Bagas hari ini hanya membawa mobil dan tidak membawa penumpang lain."],"soal":"Di sebuah pelabuhan berlaku aturan: setiap pengemudi yang membawa mobil ke kapal feri harus menunjukkan surat kendaraan dan membeli tiket kendaraan. Hari ini Bagas membawa mobil ke kapal feri di pelabuhan tersebut. Manakah kesimpulan yang pasti benar?","subtes":"Penalaran Umum"},{"bahas":"Nama tempat dan nama bulan ditulis dengan huruf kapital, sedangkan nama hari juga ditulis dengan huruf kapital. Hanya kalimat tentang kunjungan ke Candi Borobudur pada bulan Agustus yang mengikuti kaidah tersebut; kalimat lain menulis nama hari, nama tempat, atau nama kerajaan dengan huruf kecil.","id":"BPPU01","kunci":4,"opsi":["Rani belajar bahasa Indonesia setiap hari senin.","Mereka berlibur ke pantai parangtritis di Yogyakarta.","Dia membaca buku sejarah tentang kerajaan majapahit.","Siswa kelas sepuluh mengikuti lomba di jakarta.","Mereka mengunjungi Candi Borobudur pada bulan Agustus."],"soal":"Perhatikan lima kalimat berikut. Manakah yang penulisan huruf kapitalnya sudah tepat menurut EYD Edisi Kelima?","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Padi dan kapas melambangkan sila Keadilan sosial bagi seluruh rakyat Indonesia, dengan padi dan kapas menggambarkan kebutuhan pokok pangan dan sandang. Bintang melambangkan sila Ketuhanan Yang Maha Esa, rantai emas melambangkan sila Kemanusiaan yang adil dan beradab, pohon beringin melambangkan sila Persatuan Indonesia, dan kepala banteng melambangkan sila Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan.","id":"BPPU02","kunci":0,"opsi":["Keadilan sosial bagi seluruh rakyat Indonesia","Ketuhanan Yang Maha Esa","Kemanusiaan yang adil dan beradab","Persatuan Indonesia","Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan"],"soal":"Padi dan kapas pada lambang Garuda Pancasila merupakan simbol dari sila Pancasila yang berbunyi ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Selat Sunda memisahkan Pulau Sumatera dan Pulau Jawa. Selat Malaka memisahkan Pulau Sumatera dan Semenanjung Malaya, Selat Makassar memisahkan Pulau Kalimantan dan Pulau Sulawesi, Selat Lombok memisahkan Pulau Bali dan Pulau Lombok, dan Selat Bali memisahkan Pulau Jawa dan Pulau Bali.","id":"BPPU03","kunci":2,"opsi":["Selat Malaka","Selat Makassar","Selat Sunda","Selat Lombok","Selat Bali"],"soal":"Selat yang memisahkan Pulau Sumatera dan Pulau Jawa adalah ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Dalam Sistem Satuan Internasional, satuan gaya adalah newton. Joule merupakan satuan energi, watt merupakan satuan daya, pascal merupakan satuan tekanan, dan ampere merupakan satuan kuat arus listrik.","id":"BPPU04","kunci":1,"opsi":["Joule","Newton","Watt","Pascal","Ampere"],"soal":"Dalam Sistem Satuan Internasional (SI), satuan untuk gaya adalah ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Tongkonan merupakan rumah adat masyarakat Toraja di Sulawesi Selatan, dikenal dengan atap yang melengkung menyerupai perahu. Daerah lain memiliki rumah adat sendiri dengan nama dan bentuk yang berbeda, bukan Tongkonan.","id":"BPPU05","kunci":3,"opsi":["Sumatera Barat","Jawa Tengah","Kalimantan Timur","Sulawesi Selatan","Nusa Tenggara Timur"],"soal":"Rumah adat Tongkonan dengan atap melengkung menyerupai perahu berasal dari daerah ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Bacaan menggambarkan kader yang mengukur tekanan darah, mengingatkan jadwal obat, mencatat hasil pemeriksaan, dan menyarankan pemeriksaan lanjutan, sehingga warga lanjut usia merasa diperhatikan dan puskesmas mengetahui kondisi warga lebih awal. Manfaat-manfaat tersebut dirangkum dalam gagasan bahwa kunjungan rutin kader membantu warga lanjut usia memantau kesehatan dan terhubung dengan layanan kesehatan. Gagasan tentang buku kecil saja, kebutuhan kader setiap hari, pengukuran setiap hari, atau pendampingan keluarga hanya mencakup sebagian isi bacaan atau menambah hal yang tidak dinyatakan.","id":"BPBM01","kunci":3,"opsi":["Warga lanjut usia harus selalu membawa buku kecil setiap kali bepergian ke mana pun.","Puskesmas membutuhkan lebih banyak kader agar semua warga dapat dilayani setiap hari.","Tekanan darah warga lanjut usia harus diukur setiap hari agar tetap sehat.","Kunjungan rutin kader membantu warga lanjut usia memantau kesehatan dan terhubung dengan layanan kesehatan.","Keluarga warga lanjut usia sebaiknya selalu mendampingi setiap kunjungan kader."],"soal":"Kader kesehatan di sebuah kecamatan mengunjungi rumah warga lanjut usia setiap dua minggu. Pada setiap kunjungan, kader mengukur tekanan darah, menanyakan keluhan yang dirasakan, dan mengingatkan jadwal minum obat. Kader juga mencatat hasil pemeriksaan dalam buku kecil yang dibawa warga ketika berobat ke puskesmas. Bila menemukan keluhan yang memerlukan penanganan lebih lanjut, kader menyarankan warga segera memeriksakan diri dan membantu menghubungi keluarga. Kegiatan ini membuat warga lanjut usia merasa diperhatikan, sekaligus membantu puskesmas mengetahui kondisi kesehatan warga lebih awal. Kunjungan rutin itu menjadi jembatan antara warga dan layanan kesehatan di wilayah tersebut. Gagasan utama bacaan tersebut adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Petani menunda atau mempercepat penanaman berdasarkan prakiraan hujan dan mengatur jadwal pemupukan agar pupuk tidak tercuci hujan deras. Setelah satu musim, benih yang terbuang berkurang dan jadwal kerja menjadi lebih teratur. Hal itu menunjukkan informasi prakiraan cuaca membantu petani mengatur waktu tanam dan pemupukan dengan lebih tepat. Bacaan tidak menyatakan gagal panen hilang sepenuhnya, tidak menyatakan peran penyuluh tergantikan, tidak menyatakan hujan dapat dicegah, dan tidak membatasi penanaman hanya pada hari pesan diterima.","id":"BPBM02","kunci":1,"opsi":["Semua petani di desa itu kini tidak pernah mengalami gagal panen dalam keadaan apa pun.","Informasi prakiraan cuaca membantu petani mengatur waktu tanam dan pemupukan dengan lebih tepat.","Pesan singkat telah menggantikan seluruh peran penyuluh pertanian di desa tersebut.","Hujan lebat selalu dapat dicegah bila petani membaca pesan singkat setiap Senin.","Penanaman padi hanya boleh dilakukan pada hari Senin pagi setelah pesan diterima."],"soal":"Petani padi di sebuah desa mulai menerima pesan singkat berisi prakiraan hujan untuk tujuh hari ke depan. Pesan itu dikirim oleh petugas penyuluh setiap Senin pagi dan dibaca bersama di balai pertemuan tani. Dengan informasi tersebut, petani dapat menunda penanaman bila hujan lebat diperkirakan turun, atau mempercepat penanaman bila beberapa hari ke depan diperkirakan cerah. Petani juga mengatur jadwal pemupukan agar pupuk tidak tercuci hujan deras. Setelah satu musim, banyak petani mengaku benih yang terbuang berkurang dan jadwal kerja di sawah menjadi lebih teratur. Informasi cuaca yang sederhana itu kini menjadi bagian dari kebiasaan bertani di desa tersebut. Berdasarkan bacaan tersebut, dapat disimpulkan bahwa ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Dalam konteks bacaan, jalur khusus bus dan pengaturan lampu lalu lintas membuat waktu tempuh bus lebih singkat, jumlah penumpang meningkat, dan jalan tetap terbuka bagi kendaraan lain. Makna tersebut sesuai dengan mengurangi kepadatan dengan mengatur arus kendaraan agar lebih lancar. Makna harfiah tentang benang, penutupan jalan, pemindahan seluruh kendaraan, atau penundaan perjalanan tidak sesuai dengan isi bacaan.","id":"BPBM03","kunci":4,"opsi":["memisahkan benang atau tali yang kusut menjadi lurus kembali","menutup jalan utama agar tidak dapat dilalui kendaraan lain sama sekali","memindahkan seluruh kendaraan dari jalan utama ke jalan yang lain","menunda perjalanan warga sampai jalan utama menjadi sepi kembali","mengurangi kepadatan dengan mengatur arus kendaraan agar lebih lancar"],"soal":"Salah satu jalan utama kota sering padat pada jam berangkat dan pulang kerja. Pemerintah kota kemudian membuat jalur khusus bus di jalan tersebut, lengkap dengan rambu yang jelas dan petugas yang mengatur kendaraan yang melintas. Lampu lalu lintas di beberapa persimpangan juga diatur agar bus mendapat giliran lebih awal. Setelah jalur itu beroperasi, waktu tempuh bus menjadi lebih singkat dan jumlah penumpang meningkat. Jalur khusus itu mengurai kepadatan di jalan utama tanpa menutup jalan bagi kendaraan lain. Warga yang semula ragu kini mulai beralih ke bus karena perjalanan terasa lebih teratur dan dapat diperkirakan waktunya. Kata 'mengurai' dalam bacaan tersebut bermakna ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Kalimat terakhir mengulang kata pelatihan, menggabungkan penanda sangat dan sekali, serta mengulang kata mereka dan gagasan mencatat penjualan. Kalimat yang efektif menyampaikan gagasan yang sama secara ringkas dengan susunan subjek dan predikat yang jelas, tanpa pengulangan kata dan tanpa penanda penguat ganda: pelatihan membantu pedagang mencatat penjualan harian dengan ponsel. Susunan lain masih mempertahankan pengulangan kata pelatihan, penguat ganda, atau pengulangan kata mereka sehingga tetap bertele-tele.","id":"BPBM04","kunci":0,"opsi":["Pelatihan ini membantu pedagang mencatat penjualan harian dengan ponsel.","Pelatihan ini adalah pelatihan yang sangat bermanfaat sekali karena pelatihan ini membantu pedagang mencatat penjualan mereka setiap hari dengan ponsel mereka.","Pelatihan yang sangat bermanfaat sekali ini adalah pelatihan yang membuat para pedagang menjadi bisa mencatat penjualan mereka dengan ponsel mereka setiap hari.","Pelatihan ini membuat para pedagang menjadi bisa menggunakan ponsel mereka untuk mencatat penjualan mereka yang setiap hari mereka lakukan.","Pelatihan ini adalah pelatihan yang bermanfaat karena para pedagang menjadi bisa menggunakan ponsel mereka untuk mencatat penjualan mereka setiap hari."],"soal":"Di sebuah pelabuhan kecil, pedagang ikan mengikuti pelatihan penggunaan ponsel pintar selama tiga pertemuan. Pelatih menunjukkan cara mencatat hasil penjualan, menghitung uang yang diterima, dan mengirim pesan kepada pembeli tetap. Para pedagang berlatih langsung dengan ponsel masing-masing sambil didampingi relawan. Mereka juga belajar menyimpan nomor pembeli dan menandai pembeli yang sudah membayar. Suasana pelatihan berlangsung santai dan para peserta saling membantu. Pelatihan ini adalah pelatihan yang sangat bermanfaat sekali karena pelatihan ini membuat para pedagang menjadi bisa menggunakan ponsel mereka untuk mencatat penjualan mereka setiap hari. Kalimat terakhir bacaan tersebut tidak efektif karena bertele-tele. Perbaikan kalimat yang paling efektif adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Kata depan di yang menyatakan tempat ditulis terpisah dari kata yang mengikutinya sehingga bentuk yang tepat adalah di sawah. Nama hari ditulis dengan huruf kapital sehingga bentuk yang tepat adalah Minggu. Nama desa ditulis dengan huruf kapital sehingga bentuk yang tepat adalah Sumberrejo, Karanganyar, dan Sidomulyo. Tanda koma dipakai sebelum kata dan pada pemerincian tiga unsur atau lebih. Bentuk yang memenuhi seluruh kaidah tersebut adalah kalimat dengan di sawah, Minggu, nama desa yang memakai huruf kapital, dan pemerincian yang memakai koma sebelum dan.","id":"BPBM05","kunci":2,"opsi":["Kegiatan ini dilaksanakan di sawah setiap hari minggu dan diikuti oleh petani dari sumberrejo, karanganyar dan sidomulyo.","Kegiatan ini dilaksanakan disawah setiap hari Minggu dan diikuti oleh petani dari Sumberrejo, Karanganyar dan Sidomulyo.","Kegiatan ini dilaksanakan di sawah setiap hari Minggu dan diikuti oleh petani dari Sumberrejo, Karanganyar, dan Sidomulyo.","Kegiatan ini dilaksanakan di sawah setiap hari Minggu dan diikuti oleh petani dari sumberrejo, karanganyar, dan sidomulyo.","Kegiatan ini dilaksanakan di sawah setiap hari minggu dan diikuti oleh petani dari Sumberrejo, Karanganyar, dan Sidomulyo."],"soal":"(1) Kelompok tani Desa Sumberrejo mengadakan pelatihan pembuatan pupuk dari sisa tanaman untuk petani desa. (2) Pelatihan ini bertujuan mengolah sisa tanaman menjadi pupuk dan mengurangi sampah di sekitar sawah. (3) Kegiatan ini dilaksanakan disawah setiap hari minggu dan diikuti oleh petani dari sumberrejo, karanganyar dan sidomulyo. (4) Peserta belajar memilah sisa tanaman, mencampur bahan dengan takaran yang tepat, dan menjaga kelembapan tumpukan pupuk selama proses berlangsung. (5) Hasil pupuk terbaik digunakan bersama di sawah kelompok agar warga dapat melihat manfaat pengolahan sisa tanaman secara langsung. Perbaikan kalimat (3) sesuai EYD Edisi Kelima adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Sebanyak 20% dari 400 kg adalah 80 kg sehingga gabah yang tersisa setelah pengiriman ke penggilingan adalah 320 kg. Sebanyak 25% dari 320 kg adalah 80 kg sehingga gabah yang masih tersisa di gudang adalah 320 kg dikurangi 80 kg, yaitu 240 kg. Pengiriman tahap berikutnya dihitung dari gabah yang tersisa, bukan dari jumlah awal, sehingga total pengiriman bukan 45% dari 400 kg.","id":"BPK01","kunci":2,"opsi":["220 kg","260 kg","240 kg","280 kg","300 kg"],"soal":"Sebuah gudang menyimpan 400 kg gabah. Sebanyak 20% gabah tersebut dikirim ke penggilingan. Kemudian, 25% dari gabah yang tersisa dikirim ke pasar. Berapa kilogram gabah yang masih tersisa di gudang?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Selisih perbandingan adalah 5 dikurangi 3, yaitu 2 bagian, dan selisih tersebut setara dengan 40 ekor sehingga satu bagian setara dengan 20 ekor. Jumlah perbandingan adalah 5 ditambah 3, yaitu 8 bagian, sehingga jumlah seluruh ikan adalah 8 dikali 20 ekor, yaitu 160 ekor. Sebagai pemeriksaan, jumlah ikan lele adalah 100 ekor dan jumlah ikan nila adalah 60 ekor, dengan selisih 40 ekor.","id":"BPK02","kunci":4,"opsi":["120 ekor","140 ekor","150 ekor","180 ekor","160 ekor"],"soal":"Perbandingan jumlah ikan lele dan ikan nila di sebuah kolam adalah 5:3. Jumlah ikan lele 40 ekor lebih banyak daripada jumlah ikan nila. Berapa jumlah seluruh ikan di kolam tersebut?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Setiap suku diperoleh dengan menjumlahkan dua suku sebelumnya: 2 ditambah 3 sama dengan 5, 3 ditambah 5 sama dengan 8, dan 5 ditambah 8 sama dengan 13. Suku berikutnya adalah 8 ditambah 13, yaitu 21.","id":"BPK03","kunci":1,"opsi":["18","21","19","20","22"],"soal":"Perhatikan barisan bilangan berikut: 2, 3, 5, 8, 13, ... Bilangan berikutnya dalam barisan tersebut adalah ...","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Tinggi segitiga dapat dicari dari segitiga siku-siku yang dibentuk oleh tinggi, setengah alas, dan sisi yang sama panjang. Setengah alas adalah 6 cm dan sisi yang sama panjang adalah 10 cm, sehingga tinggi sama dengan akar dari 100 dikurangi 36, yaitu akar dari 64, yaitu 8 cm. Luas segitiga adalah setengah dikali alas dikali tinggi, yaitu setengah dikali 12 dikali 8, yaitu 48 cm². Sisi yang sama panjang bukan tinggi segitiga, sehingga mengalikan alas dengan sisi tersebut menghasilkan luas yang keliru.","id":"BPK04","kunci":3,"opsi":["60 cm²","30 cm²","96 cm²","48 cm²","40 cm²"],"soal":"Sebuah segitiga sama kaki memiliki alas 12 cm dan masing-masing sisi yang sama panjang berukuran 10 cm. Berapa luas segitiga tersebut?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Jumlah hasil tangkapan selama lima hari adalah 18 + 22 + 20 + 24 + 16 = 100 kg. Rata-rata hasil tangkapan per hari diperoleh dengan membagi 100 kg dengan 5, yaitu 20 kg.","id":"BPK05","kunci":0,"opsi":["20 kg","19 kg","21 kg","22 kg","18 kg"],"soal":"Hasil tangkapan ikan seorang nelayan selama lima hari berturut-turut adalah 18 kg, 22 kg, 20 kg, 24 kg, dan 16 kg. Berapa rata-rata hasil tangkapan ikan per hari?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Teks membahas perjalanan memutar yang lama, pembangunan jembatan gantung, serta dampaknya bagi anak sekolah, petani, dan warga yang sakit. Gagasan utamanya mencakup peran jembatan dalam mempersingkat perjalanan menuju sekolah, pasar, dan puskesmas, bukan hanya satu dampak atau latar belakang perjalanan memutar semata.","id":"BLBI01","kunci":0,"opsi":["Jembatan gantung mempersingkat perjalanan warga menuju sekolah, pasar, dan puskesmas.","Jalan tanah menjadi licin pada musim hujan sehingga warga harus berhati-hati.","Anak-anak di dua dusun selalu berangkat ke sekolah lebih awal setiap hari.","Petani sebaiknya membawa hasil panen ke pasar dengan sepeda motor agar tidak terlambat.","Puskesmas perlu dibangun lebih dekat dengan dusun agar warga sakit dapat dilayani lebih cepat."],"soal":"Selama bertahun-tahun, warga dua dusun yang dipisahkan sungai harus memutar jauh untuk mencapai pasar, sekolah, dan puskesmas. Perjalanan memutar itu memakan waktu lama, terutama pada musim hujan ketika jalan tanah menjadi licin. Tahun lalu, sebuah jembatan gantung dibangun di atas sungai, cukup lebar untuk pejalan kaki dan sepeda motor. Kini anak-anak berangkat ke sekolah lebih awal dan tiba dengan pakaian yang tetap rapi. Petani membawa hasil panen ke pasar tanpa khawatir terlambat, dan warga yang sakit dapat lebih cepat mencapai puskesmas. Jembatan itu mengubah perjalanan sehari-hari warga menjadi lebih singkat, aman, dan dapat diandalkan. Apa gagasan utama teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menyatakan pesan pengingat berisi nama anak, tanggal kunjungan, dan jenis imunisasi, jumlah kunjungan yang terlewat menurun, dan penimbangan serta imunisasi tetap dilakukan secara langsung di puskesmas. Teks juga menyatakan pesan pengingat hanya berfungsi mengingatkan dan tidak menggantikan pemeriksaan langsung.","id":"BLBI02","kunci":2,"opsi":["Semua ibu di kecamatan itu kini tidak pernah lagi melupakan jadwal imunisasi anaknya.","Pesan pengingat telah menggantikan penimbangan dan imunisasi di puskesmas.","Pesan pengingat membantu ibu mengingat jadwal, sedangkan pemeriksaan tetap dilakukan secara langsung.","Jumlah kunjungan yang terlewat meningkat setelah pesan pengingat mulai dikirim.","Pesan pengingat hanya berisi ajakan umum tanpa nama anak dan tanggal kunjungan."],"soal":"Puskesmas di sebuah kecamatan mulai mengirim pesan singkat pengingat dua hari sebelum jadwal imunisasi anak. Pesan itu berisi nama anak, tanggal kunjungan, dan jenis imunisasi yang akan diberikan. Sebelumnya, banyak ibu mengaku lupa jadwal karena kesibukan di sawah dan di rumah. Setelah pengingat dikirim, jumlah kunjungan yang terlewat menurun dan lebih banyak anak datang tepat pada jadwalnya. Pesan pengingat hanya berfungsi mengingatkan; penimbangan dan pemberian imunisasi tetap dilakukan secara langsung di puskesmas oleh petugas kesehatan. Petugas mencatat setiap kunjungan agar jadwal berikutnya dapat diingatkan kembali. Cara sederhana ini membantu ibu mengatur waktu tanpa menggantikan pemeriksaan langsung. Berdasarkan teks, pernyataan manakah yang sesuai dengan isi teks?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menceritakan nelayan yang mencoba alat pengering bertenaga matahari, keraguan tetangga, dan perubahan sikap setelah manfaat alat terlihat, lalu menarik simpulan bahwa cara baru lebih mudah diterima ketika manfaatnya dapat dilihat secara langsung. Cerita tersebut berfungsi sebagai contoh yang mendukung simpulan tersebut.","id":"BLBI03","kunci":4,"opsi":["Menunjukkan bahwa semua nelayan di desa pesisir telah beralih ke alat pengering bertenaga matahari.","Menjelaskan jadwal pemakaian alat pengering oleh kelompok nelayan setiap hari.","Mengajak semua nelayan membeli alat pengering bertenaga matahari secepatnya.","Membandingkan cara menjemur ikan di atas tikar dengan cara membekukan ikan di ruang pendingin.","Menunjukkan bahwa cara baru lebih mudah diterima ketika manfaatnya dapat dilihat secara langsung."],"soal":"Di sebuah desa pesisir, seorang nelayan mencoba mengeringkan ikan dengan alat pengering bertenaga matahari. Alat itu berupa kotak kaca yang menjaga ikan tetap bersih dari debu dan lalat, sekaligus mempercepat proses pengeringan. Awalnya, tetangga-tetangganya ragu karena cara itu berbeda dengan menjemur ikan di atas tikar seperti biasa. Setelah melihat ikan kering yang dihasilkan lebih bersih dan lebih cepat siap dijual, beberapa tetangga mulai mencoba alat yang sama. Dalam beberapa bulan, kelompok nelayan desa itu memiliki tiga alat pengering yang dipakai bergantian. Pengalaman ini menunjukkan bahwa cara baru lebih mudah diterima ketika manfaatnya dapat dilihat secara langsung. Perubahan tidak selalu dimulai dari perintah, melainkan dari contoh yang nyata di hadapan warga. Apa tujuan penulis menyajikan pengalaman nelayan dalam teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Pak Darman menunggu penumpang lanjut usia, membantu barang bawaan, dan memperlambat laju bus di jalan berlubang tanpa perintah atau pengumuman resmi, lalu penumpang memilih bus itu karena merasa tenang dan kembali naik bus yang sama. Rangkaian peristiwa tersebut menyiratkan perhatian kecil dan sikap sabar dapat membuat perjalanan terasa tenang dan penumpang ingin kembali.","id":"BLBI04","kunci":1,"opsi":["Pelayanan bus hanya dapat diperbaiki melalui spanduk dan pengumuman resmi di dalam bus.","Perhatian kecil dan sikap sabar dapat membuat perjalanan terasa tenang dan penumpang ingin kembali.","Pak Darman menunggu penumpang lanjut usia karena ia diperintah secara resmi oleh perusahaan bus.","Penumpang lanjut usia tidak mampu lagi naik bus tanpa bantuan pengemudi.","Memperlambat laju bus di jalan berlubang merupakan satu-satunya cara menjaga keselamatan penumpang."],"soal":"Setiap pagi, Pak Darman mengemudikan bus antar-desa melewati jalan yang sama. Ia selalu menunggu sejenak bila melihat penumpang lanjut usia berjalan menuju halte, lalu membantu menaikkan barang bawaan mereka. Di jalan yang berlubang, ia memperlambat laju bus agar penumpang tidak terkejut. Penumpang menyapanya dengan nama, dan anak-anak sekolah melambaikan tangan dari pinggir jalan. Suatu hari, seorang penumpang berkata bahwa ia memilih bus pagi itu bukan karena paling cepat, melainkan karena merasa tenang selama perjalanan. Tidak ada spanduk atau pengumuman tentang pelayanan di dalam bus itu. Namun, kebiasaan kecil Pak Darman membuat banyak penumpang kembali naik bus yang sama keesokan harinya. Apa makna tersirat dari kebiasaan Pak Darman dan tanggapan penumpang dalam teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menyatakan pendapat tentang belajar lewat video mengabaikan peran umpan balik, lalu menjelaskan video tidak dapat menjawab pertanyaan, mengetahui bagian yang belum dipahami, atau menyesuaikan penjelasan dengan kebutuhan siswa, sedangkan guru dapat bertanya kembali dan memberi contoh lain. Kelemahannya terletak pada cara menilai belajar tanpa mempertimbangkan peran umpan balik dan penyesuaian terhadap kebutuhan siswa tersebut.","id":"BLBI05","kunci":3,"opsi":["Anggapan bahwa video dapat diputar ulang kapan saja oleh siswa yang ingin belajar.","Keyakinan bahwa guru selalu memberi contoh yang sama kepada setiap siswa.","Gagasan bahwa sekolah sudah menyediakan video untuk semua mata pelajaran.","Penilaian yang mengabaikan peran umpan balik dan penyesuaian terhadap kebutuhan siswa.","Dugaan bahwa siswa menolak belajar melalui video dalam keadaan apa pun."],"soal":"Sebagian orang berpendapat bahwa belajar melalui video saja sudah cukup dan guru tidak lagi diperlukan karena semua penjelasan sudah tersedia dalam video. Pendapat ini mengabaikan peran umpan balik dalam belajar. Video tidak dapat menjawab pertanyaan siswa yang muncul saat belajar, tidak dapat mengetahui bagian mana yang belum dipahami, dan tidak dapat menyesuaikan penjelasan dengan kebutuhan setiap siswa. Guru dapat bertanya kembali, memberi contoh lain, dan membantu siswa yang tertinggal dengan cara yang berbeda. Belajar juga membutuhkan dorongan dan koreksi pada saat yang tepat, bukan hanya penjelasan yang dapat diputar ulang. Karena itu, menilai belajar hanya dari ketersediaan video adalah cara menilai yang tidak lengkap. Menurut teks, kelemahan pendapat yang menyatakan belajar melalui video saja sudah cukup terletak pada ...","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menjelaskan perjalanan panjang dan berlumpur sebelum ada layanan perahu, lalu layanan perahu yang menyeberangi teluk dalam waktu singkat, pengemudi yang mengenal siswa, dan orang tua yang merasa lebih tenang. Gagasan utama mencakup seluruh manfaat layanan perahu bagi siswa dan warga desa, bukan hanya satu rincian perjalanan.","id":"BLBE01","kunci":4,"opsi":["Children in coastal villages should always walk to school to stay healthy.","Heavy rain makes every road in the village unsafe for the whole year.","A boat driver should know every passenger by name before starting a service.","Students need dry clothes and more energy to follow lessons at school.","A school boat service helps students reach school safely and on time, supporting the whole village."],"soal":"In a coastal village, children used to walk a long way around the bay to reach school. The walk took almost an hour, and heavy rain often made the path muddy and unsafe. Last year, the village started a small boat service for students. The boat leaves in the morning, crosses the bay in fifteen minutes, and returns in the afternoon. A trusted boat driver knows every student by name and waits when a child runs late. Parents now feel calmer because the journey is shorter and supervised. Students arrive on time, with dry clothes and more energy for lessons. The boat has become an important part of school life for the whole village. What is the main idea of the passage?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Kata tersebut menggambarkan perasaan Maya yang khawatir menekan tombol yang salah, mengirim pesan kepada orang yang salah, atau kehilangan nomor pembeli, lalu berlatih perlahan dengan bantuan anaknya sebelum berani mengirim pesan. Gambaran tersebut menunjukkan perasaan ragu dan lambat bertindak, bukan perasaan gembira, marah, percaya diri, atau lelah.","id":"BLBE02","kunci":2,"opsi":["excited and eager","angry and impatient","unsure and slow to act","confident and quick","tired and bored"],"soal":"Maya sells fresh fish at a harbor market. Her daughter suggested using a phone to tell regular buyers when the morning catch arrives. At first, Maya felt hesitant. She worried about pressing the wrong button, sending a message to the wrong person, or losing the buyers' numbers. Her daughter showed her each step slowly and let her practice with family members. After a week, Maya sent her first message to five buyers. Three of them replied within minutes and reserved fish for the afternoon. Maya still checks each message twice, but she no longer feels afraid of the phone. She now uses it every morning before the market opens. The word 'hesitant' in the passage is closest in meaning to ...","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menyatakan nelayan dapat menunggu hari pasar yang lebih baik dan membuang jauh lebih sedikit ikan setelah ada ruang penyimpanan dingin, koperasi mencatat penyimpanan, dan pemimpin desa berencana membangun ruang penyimpanan lagi karena merasa puas dengan hasilnya. Rangkaian fakta tersebut menunjukkan penyimpanan dingin bersama membantu nelayan berjualan pada waktu yang lebih baik sehingga gagasan tersebut diperluas.","id":"BLBE03","kunci":0,"opsi":["Shared cold storage helped fishermen sell at better times, encouraging the village to expand it.","Village leaders forced every fisherman to use the cold storage room every day.","All fishermen in the village became wealthy soon after the storage room was built.","The cold storage room replaced fishing boats as the main source of income.","Buyers were required to pay higher prices for fish kept in the storage room."],"soal":"A fishing village built a shared cold storage room near the harbor. Fishermen bring their catch there in the morning and keep it fresh with ice until buyers arrive. Before the room existed, fishermen had to sell quickly, even when prices were low, because the fish would spoil. Now they can wait for a better market day and throw away much less fish. A cooperative keeps records of how much fish is stored and how long it stays fresh. Village leaders were pleased with the results and now plan to build a second storage room with the same simple rules. Local buyers have also noticed that the fish stays fresher than before. What can be inferred from the passage?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menyatakan petani dan pedagang pasar sering selesai bekerja terlambat dan tidak dapat meninggalkan pekerjaan pada siang hari, sehingga banyak janji temu siang hari terlewat. Alasan tersebut berkaitan dengan jadwal kerja, bukan dengan keinginan perawat, jumlah pasien siang hari, permintaan menutup sesi pagi, atau anggapan pengobatan malam lebih manjur.","id":"BLBE04","kunci":3,"opsi":["Because nurses wanted to work only in the evening and rest during the day.","Because the health center had too few patients during daytime hours.","Because mothers asked the health center to close its morning sessions.","Because many workers could not leave their jobs to attend daytime appointments.","Because evening treatment is more effective than treatment given in the morning."],"soal":"A health center in a farming town noticed that many workers missed daytime appointments. Farmers and market sellers often finished work late and could not leave their jobs during the day. In response, the health center opened evening hours twice a week. Nurses check blood pressure, give basic treatment, and answer questions about medicine. A midwife is also available for mothers who cannot come in the morning. Within three months, the number of missed appointments fell sharply. Workers say the evening hours fit their schedules and help them seek care earlier. The health center now plans to keep the evening hours and add a Saturday morning session. According to the passage, why did the health center open evening hours?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menceritakan Bapak Hartono yang belajar panggilan video pada usia lanjut, berlatih langkah demi langkah, dan akhirnya berbicara dengan cucu setiap Minggu malam sehingga jarak terasa lebih kecil. Cerita tersebut menggambarkan nilai belajar alat baru untuk tetap terhubung dengan keluarga, bukan kecepatan belajar, rasa malu, penguasaan penuh dalam waktu singkat, atau cara memilih telepon.","id":"BLBE05","kunci":1,"opsi":["To argue that older people learn new tools faster than younger people in every case.","To show that learning a new tool can help older people stay connected with family.","To suggest that video calls are embarrassing and should always be made alone.","To claim that anyone can master video calls completely within one week.","To explain the best method for choosing a phone for older people."],"soal":"At sixty-eight, Mr. Hartono had never made a video call. His grandchildren lived in another city, and phone calls made him miss their faces. His son gave him a phone and taught him one step at a time. At first, Mr. Hartono held the phone too close and spoke too loudly. With practice, he learned to frame his face, adjust the sound, and answer calls by himself. Now he talks with his grandchildren every Sunday evening. He watches them show drawings, tell stories about school, and wave goodbye before bed. Mr. Hartono says the screen does not replace a visit, but it makes the distance feel smaller. Learning the new tool gave him a way to stay close to family. What is the author's purpose in telling Mr. Hartono's story?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Dalam 2 jam, 4 mesin menggiling 960 kg gabah, sehingga satu mesin menggiling 120 kg dalam 1 jam. Untuk 5 mesin selama 3 jam: 5 x 3 x 120 = 1.800 kg.","id":"BPM01","kunci":1,"opsi":["1.440 kg","1.800 kg","1.600 kg","1.920 kg","2.000 kg"],"soal":"Sebuah penggilingan padi memiliki 4 mesin yang bekerja dengan laju sama. Keempat mesin tersebut menggiling 960 kg gabah dalam 2 jam. Jika mesin ditambah menjadi 5 mesin dan semuanya bekerja selama 3 jam dengan laju yang sama, berapa kilogram gabah yang digiling?","subtes":"Penalaran Matematika"},{"bahas":"Aturan barisan bergantian antara mengalikan dengan 3 dan mengurangi 3: 6 dikali 3 sama dengan 18, 18 dikurangi 3 sama dengan 15, 15 dikali 3 sama dengan 45, dan 45 dikurangi 3 sama dengan 42. Langkah berikutnya adalah mengalikan dengan 3, sehingga suku berikutnya adalah 42 dikali 3, yaitu 126.","id":"BPM02","kunci":3,"opsi":["39","123","45","126","129"],"soal":"Perhatikan barisan bilangan berikut: 6, 18, 15, 45, 42, ... Bilangan berikutnya dalam barisan tersebut adalah ...","subtes":"Penalaran Matematika"},{"bahas":"Jumlah tinggi lima tanaman adalah 5 dikali 42 cm, yaitu 210 cm. Jumlah tinggi enam tanaman adalah 6 dikali 44 cm, yaitu 264 cm. Tinggi tanaman tambahan adalah 264 cm dikurangi 210 cm, yaitu 54 cm.","id":"BPM03","kunci":2,"opsi":["48 cm","52 cm","54 cm","56 cm","50 cm"],"soal":"Rata-rata tinggi 5 tanaman adalah 42 cm. Setelah satu tanaman tambahan diukur, rata-rata tinggi 6 tanaman menjadi 44 cm. Berapa tinggi tanaman tambahan tersebut?","subtes":"Penalaran Matematika"},{"bahas":"Peluang mengambil kartu merah lalu kartu biru adalah 6/10 dikali 4/9, yaitu 24/90. Peluang mengambil kartu biru lalu kartu merah adalah 4/10 dikali 6/9, yaitu 24/90. Jumlah peluang tersebut adalah 48/90, yaitu 8/15.","id":"BPM04","kunci":0,"opsi":["8/15","7/15","1/2","2/5","4/9"],"soal":"Sebuah kotak berisi 6 kartu merah dan 4 kartu biru yang bentuk dan ukurannya sama. Dua kartu diambil satu demi satu secara acak tanpa pengembalian. Peluang bahwa dua kartu yang terambil berbeda warna adalah ...","subtes":"Penalaran Matematika"},{"bahas":"Jumlah penumpang pada akhir pekan adalah 240 ditambah 25% dari 240, yaitu 240 ditambah 60, yaitu 300 orang. Jumlah penumpang pada hari libur adalah 300 ditambah 20% dari 300, yaitu 300 ditambah 60, yaitu 360 orang. Persentase tahap berikutnya dihitung dari jumlah akhir pekan, bukan dari jumlah hari biasa, sehingga kenaikan total bukan 45% dari 240.","id":"BPM05","kunci":4,"opsi":["348 orang","330 orang","340 orang","372 orang","360 orang"],"soal":"Sebuah kapal feri mengangkut 240 penumpang pada hari biasa. Pada akhir pekan, jumlah penumpang 25% lebih banyak daripada hari biasa. Pada hari libur, jumlah penumpang 20% lebih banyak daripada akhir pekan. Berapa jumlah penumpang pada hari libur?","subtes":"Penalaran Matematika"}];
